// @ts-check
// Story -> files traceability read from the project repo (generated by tools/rastreio-historias.js).
const fs = require("node:fs");
const path = require("node:path");

const REL_PATH = "doc/scrum/_historias-arquivos.json";
const MAX_BYTES = 8 * 1024 * 1024;

/**
 * @param {string} repoRoot
 * @param {{ fs: typeof fs, path: typeof path }} [deps]
 * @returns {{ found: boolean, file: string, geradoEm?: string, repos?: string[], semChave?: number, historias?: Record<string, any>, error?: string }}
 */
function readStoryFiles(repoRoot, deps = { fs, path }) {
  const file = deps.path.join(repoRoot, REL_PATH);
  if (!deps.fs.existsSync(file)) return { found: false, file: REL_PATH };
  try {
    if (deps.fs.statSync(file).size > MAX_BYTES) return { found: false, file: REL_PATH, error: "Arquivo grande demais." };
    const raw = JSON.parse(deps.fs.readFileSync(file, "utf8").replace(/^﻿/, ""));
    return {
      found: true,
      file: REL_PATH,
      geradoEm: typeof raw.geradoEm === "string" ? raw.geradoEm : undefined,
      repos: Array.isArray(raw.repos) ? raw.repos.map(String) : [],
      semChave: Number.isFinite(raw.semChave) ? raw.semChave : 0,
      historias: normalize(raw.historias),
    };
  } catch (err) {
    return { found: false, file: REL_PATH, error: `JSON invalido: ${err instanceof Error ? err.message : String(err)}` };
  }
}

/** Keeps only the fields the panel renders, so a malformed file cannot inject unexpected shapes. */
function normalize(historias) {
  const out = {};
  for (const [key, h] of Object.entries(historias && typeof historias === "object" ? historias : {})) {
    if (!/^[A-Z]+-(\d+|XXX)$/.test(key) || !h || typeof h !== "object") continue;
    const repos = {};
    for (const [repo, list] of Object.entries(h.repos || {})) {
      repos[repo] = (Array.isArray(list) ? list : [])
        .filter((f) => f && typeof f.path === "string")
        .map((f) => ({ path: f.path, commits: Number(f.commits) || 0 }));
    }
    out[key] = {
      titulos: (Array.isArray(h.titulos) ? h.titulos : []).map(String),
      commits: Number(h.commits) || 0,
      repos,
    };
  }
  return out;
}

module.exports = { readStoryFiles, REL_PATH };
